head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[ModelUtil > M > findSerializedNode]<br/>Instance 내부에서 XPath 에 해당하는 노드를 찾아 직렬화(serialize)한 XML 문자열로 반환합니다.",
    "validation" : [
        "xpath(필수) 파라미터로 반환할 Instance 노드의 XPath 경로를 설정할 수 있어야 합니다.",
        "직렬화(Serialize)된 XML 문자열을 반환해야 합니다.",
        "내부적으로 findInstanceNode() 메소드를 호출한 후 결과를 직렬화하여 반환해야 합니다."
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.btn_findSerializedNode_onclick = function () {
    var scenario = par_scenario.getValue();

    if (scenario === "1") {
        // 시나리오 1 : 가이드 예제 - bookstore/book 첫번째 노드 직렬화
        wf_body_bottom.getObj("scwin").setReturnValue("── 시나리오 1 : bookstore/book (첫번째 노드 직렬화) ──");

        var xmlStr = WebSquare.ModelUtil.findSerializedNode("bookstore/book");
        wf_body_bottom.getObj("scwin").setReturnValue("반환 타입 : " + (typeof xmlStr));
        wf_body_bottom.getObj("scwin").setReturnValue("반환 문자열 : " + xmlStr);
    } else if (scenario === "2") {
        // 시나리오 2 : findInstanceNode 와 동일 노드 직렬화 결과 비교 (@spec 검증)
        wf_body_bottom.getObj("scwin").setReturnValue("── 시나리오 2 : findInstanceNode + xml.serialize 와 결과 비교 (@spec) ──");

        var directStr = WebSquare.ModelUtil.findSerializedNode("bookstore/book[2]/title");
        var nodeRef = WebSquare.ModelUtil.findInstanceNode("bookstore/book[2]/title");
        var manualStr = nodeRef ? WebSquare.xml.serialize(nodeRef) : "(null)";

        wf_body_bottom.getObj("scwin").setReturnValue("findSerializedNode 반환 : " + directStr);
        wf_body_bottom.getObj("scwin").setReturnValue("findInstanceNode + serialize : " + manualStr);
    }
};
